{"file_path":"src/lexer.js","content":"/**
 * The tokenizer for the small language described in the task prompt. It
 * turns UTF-8 source text into a list of positioned tokens, or throws a
 * `LexError` describing the first place the text stops scanning.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT_TWO = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT_ONE = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const SIMPLE_ESCAPES = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

function isLetter(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}

function isDecDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && /[0-9A-Fa-f]/.test(c)
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

function isIdentStart(c) {
  return c === '_' || isLetter(c)
}

function isIdentChar(c) {
  return c === '_' || isLetter(c) || isDecDigit(c)
}

class Cursor {
  constructor(text) {
    this.src = [...text]
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof(offset = 0) {
    return this.i + offset >= this.src.length
  }

  peek(offset = 0) {
    return this.src[this.i + offset]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.src[this.i++]
    if (c === '\n') {
      this.line += 1
      this.col = 1
    } else if (c === '\t') {
      this.col = (Math.floor((this.col - 1) / 4) + 1) * 4 + 1
    } else {
      this.col += 1
    }
    return c
  }
}

function fail(pos, reason) {
  throw new LexError(pos.line, pos.col, reason)
}

function skipTrivia(cur) {
  let moved = true
  while (moved) {
    moved = false
    while (!cur.eof() && ' \t\r\n'.includes(cur.peek())) {
      cur.advance()
      moved = true
    }
    if (!cur.eof() && cur.peek() === '/' && cur.peek(1) === '/') {
      while (!cur.eof() && cur.peek() !== '\n') cur.advance()
      moved = true
    } else if (!cur.eof() && cur.peek() === '/' && cur.peek(1) === '*') {
      const start = cur.pos()
      cur.advance()
      cur.advance()
      let depth = 1
      while (depth > 0) {
        if (cur.eof()) fail(start, 'unterminated block comment')
        if (cur.peek() === '/' && cur.peek(1) === '*') {
          cur.advance()
          cur.advance()
          depth += 1
        } else if (cur.peek() === '*' && cur.peek(1) === '/') {
          cur.advance()
          cur.advance()
          depth -= 1
        } else {
          cur.advance()
        }
      }
      moved = true
    }
  }
}

// Consumes a run of digits (per `isDigit`), allowing a single `_` between
// two digits of the run and nowhere else. Returns the consumed text.
function scanDigitRun(cur, isDigit) {
  let s = ''
  let lastWasDigit = false
  while (!cur.eof()) {
    const c = cur.peek()
    if (isDigit(c)) {
      s += cur.advance()
      lastWasDigit = true
    } else if (c === '_' && lastWasDigit && isDigit(cur.peek(1))) {
      s += cur.advance()
      lastWasDigit = false
    } else {
      break
    }
  }
  return s
}

function scanIdentifier(cur) {
  const start = cur.pos()
  let s = ''
  while (!cur.eof() && isIdentChar(cur.peek())) s += cur.advance()
  const kind = KEYWORDS.has(s) ? 'keyword' : 'ident'
  return { line: start.line, col: start.col, kind, body: s }
}

function scanNumber(cur) {
  const start = cur.pos()
  let text = ''
  let noDigitAfterPrefix = false

  if (cur.peek() === '0' && (cur.peek(1) === 'x' || cur.peek(1) === 'X')) {
    text += cur.advance()
    text += cur.advance()
    const digits = scanDigitRun(cur, isHexDigit)
    text += digits
    noDigitAfterPrefix = digits.length === 0
  } else if (cur.peek() === '0' && (cur.peek(1) === 'b' || cur.peek(1) === 'B')) {
    text += cur.advance()
    text += cur.advance()
    const digits = scanDigitRun(cur, isBinDigit)
    text += digits
    noDigitAfterPrefix = digits.length === 0
  } else if (cur.peek() === '0' && (cur.peek(1) === 'o' || cur.peek(1) === 'O')) {
    text += cur.advance()
    text += cur.advance()
    const digits = scanDigitRun(cur, isOctDigit)
    text += digits
    noDigitAfterPrefix = digits.length === 0
  } else {
    text += scanDigitRun(cur, isDecDigit)
    if (cur.peek() === '.' && isDecDigit(cur.peek(1))) {
      text += cur.advance()
      text += scanDigitRun(cur, isDecDigit)
    }
    if (cur.peek() === 'e' || cur.peek() === 'E') {
      if (isDecDigit(cur.peek(1))) {
        text += cur.advance()
        text += scanDigitRun(cur, isDecDigit)
      } else if ((cur.peek(1) === '+' || cur.peek(1) === '-') && isDecDigit(cur.peek(2))) {
        text += cur.advance()
        text += cur.advance()
        text += scanDigitRun(cur, isDecDigit)
      }
    }
  }

  let trailing = ''
  while (!cur.eof() && (isLetter(cur.peek()) || isDecDigit(cur.peek()) || cur.peek() === '_')) {
    trailing += cur.advance()
  }

  if (noDigitAfterPrefix || trailing.length > 0) {
    fail(start, `invalid number ${text}${trailing}`)
  }

  return { line: start.line, col: start.col, kind: 'number', body: text }
}

function scanEscape(cur) {
  const backslash = cur.pos()
  cur.advance() // consume backslash
  if (cur.eof()) fail(backslash, 'unterminated string')
  const ec = cur.peek()

  if (Object.prototype.hasOwnProperty.call(SIMPLE_ESCAPES, ec)) {
    cur.advance()
    return SIMPLE_ESCAPES[ec]
  }

  if (ec === 'x') {
    if (isHexDigit(cur.peek(1)) && isHexDigit(cur.peek(2))) {
      cur.advance() // x
      const h = cur.advance() + cur.advance()
      return String.fromCharCode(parseInt(h, 16))
    }
    fail(backslash, 'invalid escape \\x')
  }

  if (ec === 'u') {
    if (cur.peek(1) === '{') {
      let j = 2
      let hex = ''
      while (isHexDigit(cur.peek(j))) {
        hex += cur.peek(j)
        j += 1
      }
      if (hex.length >= 1 && cur.peek(j) === '}') {
        const cp = parseInt(hex, 16)
        if (cp <= 0x10ffff) {
          for (let k = 0; k <= j; k += 1) cur.advance()
          return String.fromCodePoint(cp)
        }
      }
    }
    fail(backslash, 'invalid escape \\u')
  }

  fail(backslash, `invalid escape \\${ec}`)
  return undefined // unreachable
}

function scanString(cur) {
  const start = cur.pos()
  cur.advance() // opening quote
  let value = ''
  for (;;) {
    if (cur.eof()) fail(start, 'unterminated string')
    const c = cur.peek()
    if (c === '"') {
      cur.advance()
      break
    }
    if (c === '\n') fail(cur.pos(), 'newline in string')
    if (c === '\\') {
      value += scanEscape(cur)
    } else {
      value += cur.advance()
    }
  }
  return { line: start.line, col: start.col, kind: 'string', body: JSON.stringify(value) }
}

function scanRawString(cur) {
  const start = cur.pos()
  cur.advance() // r
  cur.advance() // opening quote
  let value = ''
  for (;;) {
    if (cur.eof()) fail(start, 'unterminated string')
    const c = cur.peek()
    if (c === '"') {
      cur.advance()
      break
    }
    value += cur.advance()
  }
  return { line: start.line, col: start.col, kind: 'rawstring', body: JSON.stringify(value) }
}

function scanPunct(cur) {
  const start = cur.pos()
  const two = (cur.peek() ?? '') + (cur.peek(1) ?? '')
  if (PUNCT_TWO.includes(two)) {
    cur.advance()
    cur.advance()
    return { line: start.line, col: start.col, kind: 'punct', body: two }
  }
  const one = cur.peek()
  if (PUNCT_ONE.includes(one)) {
    cur.advance()
    return { line: start.line, col: start.col, kind: 'punct', body: one }
  }
  fail(start, `unexpected character ${one}`)
  return undefined // unreachable
}

/** Scans `text` into an array of tokens, or throws a `LexError`. */
export function tokenize(text) {
  const cur = new Cursor(text)
  const tokens = []
  for (;;) {
    skipTrivia(cur)
    if (cur.eof()) break
    const c = cur.peek()
    if (isIdentStart(c)) {
      tokens.push(scanIdentifier(cur))
    } else if (isDecDigit(c)) {
      tokens.push(scanNumber(cur))
    } else if (c === '"') {
      tokens.push(scanString(cur))
    } else if (c === 'r' && cur.peek(1) === '"') {
      tokens.push(scanRawString(cur))
    } else {
      tokens.push(scanPunct(cur))
    }
  }
  return tokens
}
"}

